package cn.xi.cloudwidget;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import org.json.*;
import java.io.*;
import java.time.*;
import java.util.*;

/** Water round-trip and old font/backup compatibility, also runnable on signed release. */
public class V034CompatChecks extends BackupChecks {
    void tests034()throws Exception{
        Context c=getTargetContext();Isolated source=new Isolated(c);fixture(source);Card water=Card.water();water.id="qa034-backup-water";water.waterGoalMl=2500;water.waterQuickMl=300;water.font=6;water.border=1;water.borderInk=Controls.BORDER_BLUE;water.background=0xfff4dfe3;water.addSticker("builtin:blue-sprig");LocalDate today=LocalDate.now();for(int ml:new int[]{250,300,180})water.addWater(ml,today,1700000000123L+ml);water.addWater(500,today.minusDays(1),1699900000456L);new Store(source).save(water);File archive=Backup.export(source);Map<String,byte[]> files=unzip(archive);
        Isolated empty=new Isolated(c);try(Backup.Plan plan=Backup.prepare(empty,new FileInputStream(archive))){check(plan.meta.getInt("format")==2&&plan.cards.length()==5,"new format 2 carries schema 4 and a water card with existing photo/PNG/ZIP cards");check(Backup.apply(empty,plan,Backup.NONE)==5,"water-inclusive full backup restores into an isolated empty store");}Card restored=new Store(empty).get(water.id);check(restored.waterGoalMl==2500&&restored.waterQuickMl==300&&Backup.canonical(restored.waterHistory).equals(Backup.canonical(water.waterHistory)),"water goal, quick amount, all local dates and exact timestamps survive restore");check(restored.waterTotal(today)==730&&restored.waterTotal(today.minusDays(1))==500,"restore preserves both today's and historical totals without re-bucketing timestamps");check(pixels(source,water).equals(pixels(empty,restored)),"restored decorated water card renders identically");String state=state(empty);try(Backup.Plan duplicate=Backup.prepare(empty,new FileInputStream(archive))){check(duplicate.duplicate&&Backup.apply(empty,duplicate,Backup.NONE)==0&&state(empty).equals(state),"repeated import never accumulates the same water history twice");}
        Isolated merge=new Isolated(c);Card keep=Card.water();keep.id=water.id;keep.addWater(10,today,123);new Store(merge).save(keep);new Store(merge).bind(719,"qa034-backup-water");String original=new Store(merge).get(keep.id).json().toString();try(Backup.Plan plan=Backup.prepare(merge,new FileInputStream(archive))){check(plan.conflicts==1,"water conflict is shown before confirmation");Backup.apply(merge,plan,Backup.NONE);}Card copied=null;for(Card item:new Store(merge).all())if(item.type==5&&!item.id.equals(keep.id))copied=item;check(new Store(merge).get(keep.id).json().toString().equals(original)&&new Store(merge).binding(719).equals(keep.id),"water import preserves original card and existing desktop binding");check(copied!=null&&copied.waterTotal(today)==730&&Backup.canonical(copied.waterHistory).equals(Backup.canonical(water.waterHistory)),"conflicting water card gets a new ID with complete entries copied once");
        for(String invalid:new String[]{"negative","zero","too-large","fraction","text","bad-time","late-time","empty-day","bad-date","mini","goal","quick"}){Map<String,byte[]> bad=new LinkedHashMap<>(files);JSONArray list=new JSONArray(new String(bad.get("cards.json"),"UTF-8"));JSONObject card=null;for(int n=0;n<list.length();n++)if(list.getJSONObject(n).getString("id").equals(water.id))card=list.getJSONObject(n);JSONObject entry=card.getJSONObject("waterHistory").getJSONArray(today.toString()).getJSONObject(0);
            switch(invalid){case "negative":entry.put("ml",-1);break;case "zero":entry.put("ml",0);break;case "too-large":entry.put("ml",3001);break;case "fraction":entry.put("ml",1.5);break;case "text":entry.put("ml","250");break;case "bad-time":entry.put("at",-1);break;case "late-time":entry.put("at",Long.MAX_VALUE);break;case "empty-day":card.getJSONObject("waterHistory").put(today.toString(),new JSONArray());break;case "bad-date":card.getJSONObject("waterHistory").put("2023-02-30",new JSONArray().put(new JSONObject().put("ml",250).put("at",123)));break;case "mini":card.put("shape",2);break;case "goal":card.put("waterGoalMl",10001);break;case "quick":card.put("waterQuickMl",3001);break;}
            bad.put("cards.json",list.toString().getBytes("UTF-8"));updateInventory(bad);rejected(merge,bad,"invalid water "+invalid);
        }
        File legacy=new File(source.getCacheDir(),"original-v033.zip");try(InputStream in=getContext().getAssets().open("v033-backup.zip")){Backup.write(legacy,Io.read(in));}try(Backup.Plan plan=Backup.prepare(new Isolated(c),new FileInputStream(legacy))){check(plan.meta.getInt("format")==1&&plan.cards.length()==4&&plan.cards.getJSONObject(0).getInt("schema")==4,"an actual v033 format-1 backup validates and migrates in memory");}
        Map<String,byte[]> old=unzip(legacy);JSONArray cards=new JSONArray(new String(old.get("cards.json"),"UTF-8"));cards.getJSONObject(0).put("font",3);String originalId=cards.getJSONObject(0).getString("id");old.put("cards.json",cards.toString().getBytes("UTF-8"));JSONObject metadata=new JSONObject(new String(old.get("backup.json"),"UTF-8"));metadata.put("backupId",UUID.randomUUID().toString());metadata.getJSONArray("fonts").put(new JSONObject().put("id",3).put("name","思源宋体").put("sha256","78aa7a328fd974df2d688c8a9fd74a33d8334dfa84ab24d9d11efb2ffc464117"));old.put("backup.json",metadata.toString().getBytes("UTF-8"));updateInventory(old);Isolated oldTarget=new Isolated(c);String before=state(oldTarget);try(Backup.Plan plan=Backup.prepare(oldTarget,new ByteArrayInputStream(zip(old)))){check(plan.fontFallbackCards==1&&plan.summary().contains("思源宋体已移除，将使用系统默认"),"legacy font 3 shows explicit fallback in the import preview");check(state(oldTarget).equals(before),"legacy-font validation does not change existing data before confirmation");Backup.apply(oldTarget,plan,Backup.NONE);}check(new Store(oldTarget).get(originalId).font==0,"legacy font 3 imports as system default rather than another custom font");check(Renderer.font(c,3)==Typeface.DEFAULT&&FontCatalog.fingerprint(c,3).equals("system-default"),"removed font ID is a safe tombstone that never reads serif.otf");check(Arrays.equals(FontCatalog.VISIBLE_IDS,new int[]{0,1,2,4,5,6}),"visible font IDs omit 3 without renumbering 4/5/6");boolean missing=false;try(InputStream ignored=c.getAssets().open("fonts/serif.otf")){}catch(IOException expected){missing=true;}check(missing,"target APK does not contain serif.otf");
        Card tombstone=Card.from(cards.getJSONObject(0).toString());new Store(oldTarget).save(tombstone);String unchanged=new Store(oldTarget).get(tombstone.id).json().toString();File reexport=Backup.export(oldTarget);check(new Store(oldTarget).get(tombstone.id).json().toString().equals(unchanged),"exporting a legacy font card leaves the saved original unchanged");try(Backup.Plan plan=Backup.prepare(new Isolated(c),new FileInputStream(reexport))){check(plan.fontFallbackCards==0&&plan.cards.getJSONObject(0).getInt("font")==0,"new backup normalizes deprecated font to system default without bundling old glyphs");}
        check(contrast(Controls.BORDER_BLUE,0xfffff2e3)>contrast(0xffdce9f3,0xfffff2e3)&&contrast(Controls.BORDER_GREEN,0xfffff2e3)>contrast(0xffdfe9dc,0xfffff2e3),"new border blue and green contrast more strongly against cream than old presets");
        Card sized=Card.water();sized.title="";sized.size=14;String smallText=pixels(c,sized);sized.size=26;check(!pixels(c,sized).equals(smallText),"water numeric text responds to font size even with an empty title");
        Backup.remove(archive.getParentFile());Backup.remove(reexport.getParentFile());
    }
    double contrast(int a,int b){double x=Controls.luminance(a),y=Controls.luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
    @Override public void onStart(){target=getTargetContext();Bundle result=new Bundle();try{tests034();result.putString("stream",report+"Checks passed this run: "+count+"\n");finish(Activity.RESULT_OK,result);}catch(Throwable error){result.putString("stream",report+"FAIL "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
